from math import isqrt

def is_rational_prime(n):
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0:
        return False
    r = isqrt(n)
    d = 3
    while d <= r:
        if n % d == 0:
            return False
        d += 2
    return True

def is_gaussian_prime(a, b):
    if a != 0 and b != 0:
        return is_rational_prime(a*a + b*b)
    if a == 0 and b == 0:
        return False
    v = abs(a) if b == 0 else abs(b)
    if v % 4 == 3 and is_rational_prime(v):
        return True
    return False

def longest_from(cur, used, pset, dirs, cap):
    best = 1
    dx, dy = cur
    for ux, uy in dirs:
        nxt = (dx + ux, dy + uy)
        if nxt in pset and nxt not in used:
            used.add(nxt)
            length = 1 + longest_from(nxt, used, pset, dirs, cap)
            used.remove(nxt)
            if length > best:
                best = length
            if best > cap:
                return best
    return best

def verify(witness):
    N = int(witness['bound_radius'])
    max_allowed = int(witness['max_allowed_chain_length'])
    assert N > 0 and max_allowed > 0, 'bad witness parameters'
    pset = set()
    for x in range(-N, N + 1):
        for y in range(-N, N + 1):
            if is_gaussian_prime(x, y):
                pset.add((x, y))
    assert len(pset) > 0, 'no Gaussian primes found in window'
    dirs = [(1,0),(-1,0),(0,1),(0,-1)]
    best = 0
    for p in sorted(pset):
        length = longest_from(p, {p}, pset, dirs, max_allowed)
        if length > best:
            best = length
        assert best <= max_allowed, 'FAIL: unit-step chain of length ' + str(best) + ' exceeds bound ' + str(max_allowed) + ' starting at ' + str(p)
    return best
